BEGIN;

WITH seed AS (
  SELECT *
  FROM jsonb_to_recordset($json$[{"id":100001,"title":"英雄之旅总览：把生命当作创造与疗愈的冒险","content":"英雄之旅不是追逐名利的个人奋斗剧本，而是一种把生命视为伟大冒险的意识训练：人被某种更深的力量触碰，离开惯性的生活方式，经历失联、磨难、失败、整合与疗愈，最后带着获得的礼物回到世界，贡献给他人。课程正文把这一主线放在当代处境中理解：人很容易陷入负面念头、焦虑、抑郁、过度分析和小我身份，因而失去与生命力、创造力、身体和世界的连接。所谓正能量人生，并不是永远顺利，而是能全身心参与生命，在困难中保持开放，把痛苦转化为更完整的人性。整个十二模块可视为一条路径：听见召唤，看见拒绝，找到向导，训练创造性心智，连接资源，召回温柔、勇猛、顽皮等原型能量，把障碍和恶魔转化为资源，再把礼物传给他人。英雄之旅的核心价值，是让个人从孤立的小我走向身心灵整合，再走向社群与世界的疗愈；每个人都携带一份独特礼物，旅程的意义在于听见它、训练自己承载它、并把它分享出去。它不是一次顿悟，也不是外部成就清单，而是持续的身心练习：安顿、呼吸、放下固化形式，重新选择如何回应生命。用于问答检索时，可对应生命意义、创造力低落、人生卡住、痛苦转化、如何贡献社会等问题。","tags":["英雄之旅","创造力","疗愈整合","正能量人生","生命礼物","社群贡献"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":10},{"id":100002,"title":"聆听召唤：从童年火光到一生价值的辨认","content":"召唤不是头脑临时想出的目标，而是生命中反复触碰你的深层信号。它可能来自童年第一次被某个人、一本书、一首音乐、一个科学家或艺术家点亮的瞬间，也可能来自一次巨大的痛苦之后的重生，或来自想象临终回望时会让自己说出此生值得的价值。课程强调，人常被左脑的过度分析锁住，越努力想答案，越难听见召唤；所以练习不是思考清单，而是先安顿身体、呼吸、向天空伸展、向大地释放，再把问题像种子一样投入全身心，让画面、记忆和感受自然浮现。可反复询问：小时候谁启发了我，哪次挣扎让我更有生命力，哪个艺术作品打开过我，若生命将尽我希望完成什么。召唤常常短暂，却不会消失；它像内在已经存在的火，提醒你什么能让生命鲜活、快乐、神奇，也提醒你如何成为更好的自己并帮助别人。当出现多个答案时，不必急着选择哪一个正确，而是观察哪个让身体更放松、更有热、更多泪水或敬畏；这些生理反应常比逻辑判断更接近召唤。","tags":["召唤","童年记忆","生命使命","身心练习","价值澄清","创造力"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":20},{"id":100003,"title":"拒绝召唤与找到向导：把“不可能”转化为支持","content":"当一个人感到自己想创造某种生命、事业或关系时，拒绝召唤几乎会同步出现。它可能是父母、家庭、社会、性别角色、职业规划或内在批评者的声音，反复说你不能、你不该、那不现实。课程没有把这部分视为错误，而把它看成英雄之旅必经的张力：心中的渴望和头脑中的限制讯息同时存在，真正的成熟不是假装没有阻力，而是能与阻力同场工作。练习的关键，是先触碰心，说出我最想创造的是什么，并让身体做出代表梦想的动作；再走到另一边，进入批评者角色，用姿态和声音表达不允许，重复几次直到能看见它的能量模式；最后请出导师、祖先、榜样或灵性向导，走进他们的身体、眼神和神态，接收支持与许可。向导可以是现实老师、亲人、已故长辈、文学人物或内在智慧。这样做不是否认批评，而是让支持系统比批评更有能量，使人能在真实世界中带着勇气迈步。","tags":["拒绝召唤","内在批评","向导","导师资源","身体模型","自我支持"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":30},{"id":100004,"title":"创造性心智：用游戏、幽默和多重视角重新连接生命","content":"创造性心智的核心是不被单一视角锁住。课程把右脑比作开放的海洋，能把任何事物连接到其他事物；左脑则像语言电脑，擅长代表、分析和控制，但如果成为唯一中心，就会让人困在机器世界，失去心灵、身体和奥秘感。创造性的人会移动、发散、玩耍、幽默，并能像孩子一样流动，同时保有成人的成熟。练习上，可以一天多次收回注意力、触碰心、打开全身通道，暂时放下固定身份，感受自己既是孩子、成年人、古老的生命、大树、动物，也是宇宙的一部分。通过身体动作、声音、笑和想象，人的小我身份会松动，生命意图便能从更广阔的创造意识中表达出来。这种玩耍不是逃避现实，而是让心智恢复灵活性。若发现自己僵硬、无趣、只能想出一种做法，正是需要进入创造性心智的信号。","tags":["创造性心智","右脑连接","左脑分析","游戏精神","多重身份","身体觉察"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":40},{"id":100005,"title":"三种心智与正念种子：静止、寂静、无边无际","content":"课程把更深的正念状态分为语言心智、身体心智和场域心智。语言心智容易担忧、解释和计划；身体心智若被紧绷占据，就会阻塞生命之气；场域心智则指人与家庭、城市、自然、社群及万有生命的连接。仅在头脑里设定目标，往往缺少直觉、自信和流动，因此需要把意图放入更精微的身心场域中。三颗种子的练习分别对应三个层面：把静止投入身体，让肌肉和姿态慢下来，像大树向下扎根又向天空打开；把寂静投入语言心智，让杂念在宽阔空间中休息，而不是用力驱赶；把无边无际投入场域心智，让涟漪从心和腹部扩散到周围一切人事物。等身体像光、头脑有寂静、场域能包容时，再说出我想在世界上创造的是什么，创造力会比紧张努力更稳定。","tags":["三种心智","正念种子","语言心智","身体心智","场域心智","生命之气"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":50},{"id":100006,"title":"三个正向连接：意图、中心与资源圆环","content":"真正把召唤带到世界，不只是想清楚目标，而是同时建立三个正向连接。第一是简洁、正向、有共振的意图，例如我最想创造的是某种关系、疗愈、平静或贡献；第二是身体中心，可能在心口、腹部或其他最有能量感的地方，当压力、未知、速度过快或注意力涣散时，回到中心就等于回到根基；第三是资源圆环，包含导师、朋友、家人、自然地点、动物、祖先、灵性存有、社群或任何能支持你走路的人事物。练习时先安顿，下沉并打开；再看见未来时间线，一步步前进，每一步都重新感受意图、中心和资源。资源不是抽象安慰，而是一个可被身体感到的场：有人看见你、爱你、理解你、支持你继续。三连可作为任何计划前的微流程：先说清意图，再摸到中心，最后看见资源；三者同时在线时，行动更有弹性和耐力。","tags":["资源连接","正向意图","身体中心","资源圆环","时间线","社群支持"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":60},{"id":100007,"title":"三种原型能量：温柔、勇猛与顽皮的整合","content":"为了让召唤能在沟通和行动中实现，课程提出三种普世原型能量：温柔、勇猛、顽皮。温柔让人先对自己良善，也能在紧张的人际氛围中建立信任和安全；但只有温柔会失去边界，所以需要勇猛的专注、火焰、决心和复原力。勇猛若脱离心灵，会变成暴力、批评或霸凌，因此必须回到人性的中心。顽皮则让人从过度严肃和僵硬中解放出来，带来笑、轻盈、好奇和创造性沟通。练习方式是为每种能量找到代表人物或榜样，进入他们的身体、眼神和姿态，再回到自己身上，用这股能量表达同一个生命意图。成熟表达是三者同时服务于心灵，而不是各自失控。冲突中若只有温柔，容易退让；只有勇猛，容易压迫；只有顽皮，容易逃避深度。","tags":["原型能量","温柔","勇猛","顽皮","沟通","创造力训练"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":70},{"id":100008,"title":"用原型能量面对障碍：合气道式地欢迎与引导","content":"障碍在英雄之旅中被称为恶魔，可能是内在恐惧、批评、失联、羞耻，也可能是外在家人、机构、工作环境或不支持你的人。课程借用艾瑞克森取向和合气道精神：不要与阻碍硬碰硬，不要暴力消灭、逃离或控制，而是先与它相合，欢迎它，再把关系带向更好的方向。练习时先站在意图和中心里，看见未来道路，再让一个具体障碍出现在前方。用正向勇猛面对它时，感受边界、眼神、站立方式和可以说出的清晰话语；用顽皮面对它时，跳舞、转圈、笑，避免把力量交给障碍；用温柔面对它时，先支持自己的脆弱，再以成熟善意触碰阻碍背后的痛苦。障碍不是旅程失败的证据，而是提醒你回到中心并调用更完整的自己。","tags":["障碍转化","恶魔","合气道","非暴力","边界","原型应用"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":80},{"id":100009,"title":"转化恶魔：从问题行为里识别正向需求","content":"问题、症状和成瘾行为表面上像敌人，深处常隐藏着尚未被看见的正向需求。课程用恶龙可能是等待被发现的礼物来说明这一点：如果只分析、压制、逃避或攻击问题，就会切断它携带的资源。更有效的方法是发展身体模型。选择一个反复让你挣扎的行为或情绪，例如焦虑、缺乏安全感、拖延、上瘾；不要急着解释，不要命令它停止，而是让身体自然做出一个姿态或重复动作，并以比平常慢数倍的节奏、温柔和好奇来体验它。然后在动作中询问：这个模式想为我创造什么，它想满足哪种正向需求。关键在于区分需求和策略：需求可能是安全、温暖、休息、连接或自由，旧策略可以被替换，但需求必须被尊重。","tags":["恶魔转化","身体模型","正向需求","症状意义","艾瑞克森","成瘾疗愈"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":90},{"id":100010,"title":"目标与障碍整合：让对立面成为同一支舞","content":"目标和障碍并不总是敌对关系，很多症状其实在尝试恢复平衡。一个人用紧绷、强硬和肌肉力量逼自己完成项目，结果拖延不断出现；拖延看似恶魔，深处却可能代表放松、休息、释放和阴性能量，提醒他不能只靠蛮力。整合练习先为目标建立身体模型，感受我真正想创造的是什么；再为每当我想创造它时被触发的那一面建立身体模型，如抑郁、自我批判、恐惧、愤怒或拖延。不要用对错评判两边，而是用缓慢、温柔、顽皮、好奇的动作欢迎每一面，倾听它各自代表的正向需求。整合后的行动不是折中妥协，而是让目标获得障碍所携带的智慧：努力获得休息，勇气获得柔软，前进获得节奏，因此更能长期持续。","tags":["目标整合","障碍整合","阴阳平衡","拖延","身体舞蹈","创造性完整"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":100},{"id":100011,"title":"传递给他人：把获得的礼物变成世界的光","content":"英雄之旅最终不是把天分囤积起来，而是传递给他人。课程通过艾瑞克森对学生的教导指出，真正的回报方式是把有用的东西继续分享。一个人在年轻时需要专注自己的目标，但当能力和成功逐渐出现，如果只追逐名利、金钱和外在认可，创造力会再次收缩；若把天赋视为被托付的礼物，并用来帮助别人，生命会更快乐、更宽广。练习上，先放下比较、表演和赚钱的压力，进入让自己感到神圣、平静、合一的空间，感受内在不可摧毁的光。分享不是拯救姿态，也不是牺牲自我，而是让自己的觉醒映照并唤醒他人的觉醒。真正分享时必须先保持自己的光，不在关系中耗尽自己，而是从充满的中心去照亮。","tags":["传递给他人","贡献","礼物","艾瑞克森","慈悲练习","社群疗愈"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":110},{"id":100012,"title":"回顾整合：把每一天活成完整的英雄之旅","content":"最后的整合练习把十二个模块收束为日常道路：先安顿、下沉大地、向天空打开，让语言像音乐和梦一样流入全身；记得自己来到世界是为了给出一份礼物，也诚实看见曾经因为不被支持而转身拒绝。然后寻找榜样、向导和能让灵魂相触的人，学习把觉知中心从头脑转回身体、心灵和场域。日常行动中，要保留玩耍、温柔、勇猛、专注和严肃的混合状态；遇到障碍时，退后一步成为大树，回到静止、寂静和无边无际，再用身体模型、合气道式欢迎和创造性好奇把冲突转为合作。英雄之旅不是一次性完成的课程，而是每一天都能重新选择的活法：过好今天，享受这一刻，并支持他人也活出他们的旅程。","tags":["回顾整合","每日练习","感恩","宽恕","宇宙连接","享受生命"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":120},{"id":100013,"title":"1号完美型：核心识别与成长建议","content":"1号的核心不是简单的爱挑剔，而是内在长期有一套高标准在审判：这件事对不对、够不够好、还能不能改进。他们把责任、秩序、原则和正确性放在快乐之前，擅长发现漏洞、维护规范、把事情做扎实。盲点是把应该当成唯一道路，把错误看成道德问题，把愤怒压成不满、讽刺、僵硬的礼貌或反复纠错。成长关键是从内在批评家退后一步，区分我想要和我应该，允许错误、风险和多种答案存在；把事实核对代替脑内定罪，把感谢与肯定说出口；给日程留白，练习享受、求助和适度妥协；把怒气视为被忽略需求的信号，用清楚、非控诉的语言表达边界。成熟的1号会把高标准转化为可靠、正直和持续改善，而不是让自己和他人永远不合格。","tags":["九型人格","1号","完美型","完美主义者","内在批评","愤怒","原则","成长建议"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":210},{"id":100014,"title":"2号助人型：核心识别与成长建议","content":"2号的核心驱动力是通过被需要、被喜欢、被认可来确认自己的价值。他们能快速捕捉他人的情绪和需求，愿意支持、照顾、连接资源，也善于让别人感觉自己很重要。盲点是注意力长期放在他人身上，自己的真实需要会变得模糊，付出容易夹带期待：我这么懂你、帮你，你是否也会爱我、重视我？得不到回应时，2号可能受伤、抱怨、控制、吃醋。成长建议是停止用过度付出来换取关系安全，帮助前先问：这是对方真正需要，还是我想证明自己重要？把隐性期待改成直接请求，允许自己接受照顾；建立边界，不把拒绝理解为不爱。成熟的2号能温暖地滋养他人，也能诚实承认自己的欲望、脆弱和限度。","tags":["九型人格","2号","助人型","给予者","被需要","认可","边界","关系"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":220},{"id":100015,"title":"3号成就型：核心识别与成长建议","content":"3号的核心关注是成功、效率、形象和可见成果：我怎样被尊敬、被认可、被证明有价值。他们行动快、目标感强、能读懂场域并切换角色，适合推动项目、包装想法、销售愿景、鼓舞团队。代价是把正在做什么误当成我是谁，把悲伤、恐惧、疲惫和亲密需求视为影响表现的干扰。成长方向是从表演自我回到诚实自我：定期停下问自己喜欢什么、不喜欢什么、身体感觉如何；把休息和情感觉察也放进日程，而非只安排产出；学习承认失败、困惑和普通时刻，不急着换项目或换形象。成熟的3号依然高效有感染力，但其价值不再完全依赖掌声。","tags":["九型人格","3号","成就型","实干者","形象","成功","工作狂","诚实"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":230},{"id":100016,"title":"4号自我型：核心识别与成长建议","content":"4号的核心经验是强烈地感到我与别人不同，并在失落、渴望、独特性和真实表达中寻找自我。他们情感细腻，能进入他人的痛苦，富有审美、创造力和意义感。盲点是注意力容易停在缺失处：现实有什么不够，别人拥有什么而我没有，理想关系为何迟迟不到；情绪会被当成身份，嫉妒、忧郁、浪漫化和戏剧性表达会反复出现。成长建议是尊重情感但不被情感定义：把我感觉如此与事实必然如此分开；在普通日常中建立稳定行动；把嫉妒当成愿望线索，转化为可执行选择；亲密关系中直接表达需要，少用疏离、戏剧化或测试来证明爱。","tags":["九型人格","4号","自我型","悲情浪漫者","情绪","嫉妒","真实","创造力"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":240},{"id":100017,"title":"5号理智型：核心识别与成长建议","content":"5号的核心策略是用观察、知识和边界来保护时间、能量与内在空间。他们擅长客观分析、系统研究、保持冷静，常在独处后才重新接触情绪。压力点在于把外界需求体验成侵入，把亲密、承诺或即时回应视为资源消耗，于是退回头脑、分隔生活领域、少说少给；情绪可能不是没有，而是被推迟到安全独处时才浮现。成长建议不是强迫外向，而是让知识与生命重新连接：在尚未准备完美时也小步参与；用简短语言告诉别人自己需要多少时间和空间，而不是消失；练习在当下辨认身体和情绪，别只事后复盘。","tags":["九型人格","5号","理智型","观察者","边界","知识","抽离","独处"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":250},{"id":100018,"title":"6号忠诚型：核心识别与成长建议","content":"6号的核心注意力在安全、信任、风险和权威：哪里会出问题，谁可靠，我的决定是否稳妥。他们能预演最坏情况，发现隐藏漏洞，对团队和承诺很忠诚。盲点是焦虑会让他们在顺从与挑战权威之间摆动，既想得到保护又担心被控制；他们可能怀疑他人动机、拖延决定、反复确认，或用反恐惧方式冲向危险来证明自己不怕。成长建议是发展内在权威：把事实、想象、直觉和投射分栏记录；为决策设定截止时间，允许足够好而非绝对安全；公开提出疑问，不在背后累积猜测；练习想象正面结果，让身体体验安全。","tags":["九型人格","6号","忠诚型","怀疑论者","安全","信任","权威","焦虑"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":260},{"id":100019,"title":"7号快乐型：核心识别与成长建议","content":"7号的核心追求是可能性、自由、快乐和未来计划。他们乐观、点子多、反应快，能把不同事物连接成新方案，擅长带来兴奋感、创新气氛和对未来的信心。盲点是害怕被限制、无聊或痛苦困住，容易用新选择、合理化、玩笑和忙碌避开难受感；承诺后仍保留退路，兴趣下降就转向下一个刺激，未完成事项堆积。成长建议是把自由从永远有别的选择升级为能选择并完成：限制同时进行的项目，给承诺设置收尾标准；遇到痛苦时先停留、呼吸、命名感受，不急着转移；评估计划时同时看风险、资源和代价。","tags":["九型人格","7号","快乐型","享乐主义者","自由","乐观","选择","逃避痛苦"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":270},{"id":100020,"title":"8号领袖型：核心识别与成长建议","content":"8号的核心关注是力量、控制、公正和真实。他们直接、有行动力，能在混乱中接管局面，保护弱者，讨厌虚伪、软弱和被蒙在鼓里。压力点在于把世界分成强者与弱者，隐藏脆弱，用愤怒、强势和报复来恢复控制，可能无意中让他人害怕或沉默。成长建议是把力量从压制转为承担：行动前先听完整信息，尤其欢迎坏消息；区分我在保护与我在控制；练习用较低强度表达需求，给别人反应时间；在可信对象面前承认害怕、在乎或受伤，不把柔软等同于失败；冲突中追求清楚和修复，而不只是胜利。","tags":["九型人格","8号","领袖型","保护者","控制","正义","愤怒","脆弱"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":280},{"id":100021,"title":"9号和平型：核心识别与成长建议","content":"9号的核心策略是维持和谐、避免冲突，并把自己融入他人的节奏。他们能倾听多方、理解不同立场、提供稳定支持，是天然的调停者。盲点是忘记自己的优先级，把重要愿望让位给琐事、习惯或他人安排，表面顺从内心保留，压力下以拖延、麻木、被动抵抗表达愤怒。成长建议是把和平从没有冲突升级为真实参与：每天写下自己的一个偏好、一个不愿意、一个下一步行动；用期限和结构帮助聚焦，先做最重要的小步骤；练习直接表达不同意见，不用拖延让别人猜；把愤怒视为生命力和边界的信号。","tags":["九型人格","9号","和平型","调停者","和谐","冲突回避","惯性","边界"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":290},{"id":100022,"title":"通用机制：注意力焦点、直觉与三大中心","content":"九型不是先看外在行为，而是看注意力被什么自动吸走。性格一旦形成，人会选择性搜集信息：1号看对错与改进，2号看别人是否需要和喜欢自己，3号看表现能否获得肯定，4号看缺失、独特和真实感，5号看边界与资源要求，6号看风险和隐藏意图，7号看快乐选择与未来可能，8号看失控、不公和力量对比，9号看他人安排与各方立场。身体中心8、9、1常通过腹部和本能感知环境；情感中心2、3、4通过关系、形象和情绪共鸣感知；精神中心5、6、7通过观察、预测和联想感知。成长入口是成为内心观察者：记录自己第一时间注意到什么、忽略什么；区分事实、解释、幻想和直觉。","tags":["九型人格","通用机制","注意力","直觉","三大中心","身体中心","情感中心","精神中心"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":310},{"id":100023,"title":"通用机制：两翼、核心动机与同型差异","content":"两翼指某个型号相邻两侧型号对其表达方式的影响。它不是另一个核心类型，也不是简单的副人格，而是让同一型号呈现不同气质的调味层：偏5翼的4号可能更内收、理性和孤僻，偏3翼的4号可能更外显、形象化和有舞台感；偏8翼的9号更硬、更能顶住压力，偏1翼的9号更克制、更在意正确与秩序。使用两翼时要避免只凭风格判断，例如一个强势的9号不等于8号，一个外向的5号也不等于7号。先问核心动机：他是在维护和谐、保留资源，还是追求自由？再看两翼怎样改变表达。两翼解释差异，不替代访谈、情境和长期注意力观察。","tags":["九型人格","通用机制","两翼","核心动机","同型差异","识别方法"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":320},{"id":100024,"title":"通用机制：压力线、安全线与状态变化","content":"每个型号不是静态标签，而是由日常主型、压力状态、安全状态共同构成。压力状态常沿箭头离开本型：1到4、2到8、3到9、4到2、5到7、6到3、7到1、8到5、9到6；安全状态常沿反向进入：1到7、2到4、3到6、4到1、5到8、6到9、7到5、8到2、9到3。使用时不要把安全线等同于一定健康、压力线等同于一定糟糕；安全也可能暴露阴影，压力也可能激发能力。关键是观察状态变化：在放松、受威胁、被爱、被批评时你变成什么样？成长不是迷恋安全态，而是能觉察三种状态、整合其正面资源，并在负面反应出现前暂停选择。","tags":["九型人格","通用机制","压力线","安全线","动态变化","九角星","状态识别"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":330},{"id":100025,"title":"通用机制：关系与职场沟通的九型用法","content":"九型用于关系和职场时，重点不是给人分类，而是找到对方的原动力、焦虑点和沟通入口。1号需要尊重其标准，同时减少你错了的羞辱感；2号需要感谢但也要鼓励其说出真实需求；3号需要目标和认可，也要提醒其关注人和过程；4号需要真实与意义，反馈要避免轻率否定其感受；5号需要提前信息、边界和思考时间；6号需要透明、稳定承诺和可验证依据；7号需要空间与愿景，同时要明确收尾责任；8号需要直说、完整信息和可信赖的边界；9号需要清晰结构、温和追问和表达异议的安全感。成熟用法是用类型翻译彼此语言：把评判译成对质量的在乎，把控制译成对安全的需求，把拖延译成冲突恐惧，再讨论可执行请求。","tags":["九型人格","关系","职场","沟通","领导力","反馈","冲突","团队管理"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":340},{"id":100026,"title":"关键对话：先恢复安全感，再讨论观点差异","content":"关键对话通常同时具备三个特征：观点不同、利害关系重大、情绪强烈。很多沟通失败不是因为道理不够，而是对话安全感已经破裂；一旦人感觉被攻击、羞辱或不被尊重，就会转入沉默或暴力：沉默包括回避、掩饰、退出，暴力包括控制、贴标签、攻击和打断。有效处理关键对话的第一步，不是立刻证明自己正确，而是观察气氛是否安全：对方是否还愿意说真话，自己是否还在听。若安全感下降，应先暂停内容争论，说明共同目的和尊重，例如“我不是要否定你，我想一起把问题解决”。然后再陈述事实、表达感受、解释自己的故事、询问对方看法。App 问答可用于伴侣冲突、上下级反馈、客户沟通和团队分歧。","tags":["关键对话","沟通","安全感","冲突","反馈","沉默","暴力"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":410},{"id":100027,"title":"非暴力沟通四步：观察、感受、需要、请求","content":"非暴力沟通的核心，是把注意力从评判、指责、命令和辩解，转向人真实的观察、感受、需要和请求。第一步是观察：具体说发生了什么，避免“你总是”“你从来不”等概括性评价。第二步是感受：表达自己身体和情绪的真实状态，如失落、担心、疲惫、安心，而不是伪装成感受的指责。第三步是需要：为自己的感受负责，看到背后未被满足的需要，如尊重、休息、连接、自由、安全、理解。第四步是请求：提出具体、可执行、当下可回应的请求，而不是模糊期待或命令。它并非软弱妥协，而是让双方从敌对意识回到生命需要。适合回答亲密关系争吵、亲子沟通、职场表达、如何提出边界和如何道歉。","tags":["非暴力沟通","观察","感受","需要","请求","同理心","关系修复"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":420},{"id":100028,"title":"情绪急救：拒绝、孤独、失败和反刍需要及时处理","content":"日常心理伤害也需要像身体伤口一样做急救。拒绝会带来尖锐痛感，削弱自尊和归属感；孤独会让人更敏感、更防御，甚至把真正能靠近的人推开；失败容易让人把一次结果扩大成对自我的否定；反刍会让痛苦反复激活，形成焦虑和抑郁倾向。情绪急救的第一原则是尽早处理，而不是硬扛。可以先给情绪命名，承认痛苦真实存在；再把事件与自我价值拆开，避免“我被拒绝=我不值得”；随后做具体修复：联系安全的人、恢复日常行动、减少反复回放、写下可学习之处。若痛苦持续影响睡眠、工作、饮食、现实判断或有自伤风险，应寻求专业帮助。App 可用于被拒绝、失恋、孤独、失败、自卑和内耗等场景。","tags":["情绪急救","拒绝","孤独","失败","反刍","自尊","心理创伤"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":430},{"id":100029,"title":"自控力：先观察失控模式，再设计环境","content":"自控不是靠羞辱自己变强，而是成为自己的观察者，理解何时、何地、因为什么失控。很多人越相信自己意志坚定，越容易把自己暴露在诱惑中；一旦失败，又因为意外和羞耻而放弃。更有效的方法是像科学家一样收集数据：什么时候最容易拖延，什么情绪会触发消费或暴食，哪些人、地点、App 或疲劳状态会削弱自控。然后设计环境而不是只发誓：减少诱惑可见度，提前设定下一步动作，把长期目标和眼前选择连接起来，用小实验测试哪种方法有效。自控力还包含“我要做”“我不要”“我想要”三种力量：不仅要抵制诱惑，也要记得真正重要的目标。App 可用于拖延、成瘾、情绪性消费、减肥、学习和习惯改变。","tags":["自控力","意志力","拖延","习惯改变","观察者","诱惑","目标"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":440},{"id":100030,"title":"解决冲突：把冲突当作信息，而不是立即消灭","content":"冲突不可完全避免，重要的是把它当作信息入口，而不是马上逃跑、压制或赢过对方。高质量冲突处理从理解发生了什么开始：双方各自看到了什么事实，分别受到什么影响，各自真正关心什么。很多人一遇冲突就急着解决，反而没弄清原因；也有人任由敌意升级，错失修复机会。有效做法是先降低攻击性表达，帮助聆听和说话变得容易：少用指责，多用具体事件；少说“你就是”，多问“你当时看到的是什么”；承认对方处境，同时表达自己的边界和请求。冲突的目标不是双方都委屈地妥协，而是找到能照顾重要需要的新路径。App 可用于伴侣冷战、团队矛盾、朋友误会、谈判和家庭分歧。","tags":["解决冲突","聆听","对话","边界","关系修复","谈判","误会"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":450},{"id":100031,"title":"创伤反应：身体会记住未完成的危险","content":"创伤并不只是记忆里的一段故事，也会保存在身体、神经系统和关系反应中。经历过创伤的人可能明知现在安全，却在类似声音、气味、表情、距离或权威情境中突然紧绷、麻木、愤怒、逃离或讨好；这不是矫情，而是身体在用旧系统保护自己。疗愈的核心之一是重新建立安全与调节能力：先识别触发点和身体信号，再用呼吸、地面感、身体移动、稳定关系和可预测环境帮助神经系统回到当下。不要急着逼自己讲完所有创伤细节，身体安全比叙事完整更基础。关系中，创伤者需要被看见、被尊重节奏，而不是被催促“想开点”。App 可用于惊恐、麻木、过度警觉、亲密关系触发和创伤后自我理解。","tags":["创伤疗愈","身体记忆","安全感","神经系统","触发点","情绪调节","依恋"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":460},{"id":100032,"title":"回避型模式：逃避情绪会让关系和自我更空","content":"回避型或逃避型人格模式常见于对拒绝、失望、犯错和暴露脆弱高度敏感的人。为了不被伤害，他们会隐藏不安全感，努力保持理性、独立、无所谓，甚至把真实情绪像流感一样躲开。短期看，逃避能减少痛苦；长期看，它会让人失去与自己和他人的情绪连接，形成空虚、焦虑、亲密困难和自我价值感低落。成长不是一次性冲进情绪，而是安全地接触：当想逃跑、责备或麻木时，先停下，命名身体感受和脑中故事；区分真实事件与旧信念；用小剂量表达需要和脆弱，观察关系是否真的崩塌。App 可用于回避亲密、不敢表达、不安全依恋、内心空虚和情绪逃避。","tags":["回避型人格","不安全依恋","情绪逃避","亲密关系","脆弱","自我价值","焦虑"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":470},{"id":100033,"title":"边界表达：清楚说不，不等于伤害关系","content":"很多关系问题不是缺少爱，而是缺少清楚边界。没有边界的人容易讨好、压抑、拖延、爆发；边界过硬的人则可能控制、隔离、拒绝连接。健康边界是既承认关系重要，也承认自己的时间、身体、情绪和价值同样重要。表达边界时，先具体说明事实和影响，再表达自己的限制和可提供的替代方案，例如“我今晚需要休息，不能继续讨论；明天十点我可以认真听你说”。边界不是惩罚，也不是让对方猜，而是让关系可持续。若对方不适应你的新边界，不代表你错了；这只是关系系统在重新调整。App 可用于不会拒绝、被索取、关系内耗、职场加班、人情压力和亲密关系空间。","tags":["边界","拒绝","讨好","关系内耗","自我照顾","沟通","亲密关系"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":480},{"id":100034,"title":"行动改变：把大目标拆成可重复的小实验","content":"无论是九型成长、英雄之旅还是自控力训练，真正改变都需要从宏大愿望落到小实验。大目标容易激发热情，也容易引发压力、完美主义和拖延；小实验则让人用数据学习，而不是用自责消耗。设计实验时要明确：我要观察什么，下一步最小行动是什么，何时做，做完如何记录。比如想改善沟通，不是发誓以后不吵架，而是每次冲突前先说一个事实、一个感受、一个请求；想减少拖延，不是要求自己从此自律，而是先开始5分钟并记录触发点。失败不是人格失败，而是实验数据，提醒你调整环境、节奏、支持或目标。App 可用于习惯养成、学习计划、关系修复、情绪管理和职业目标推进。","tags":["行动改变","小实验","习惯养成","拖延","目标拆解","复盘","成长练习"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":490},{"id":100035,"title":"关系修复：先承认影响，再解释动机","content":"关系受伤后，很多人急着解释自己不是故意的，却忽略对方已经受到影响。修复对话应先承认事实和影响：我看到我刚才打断你，让你觉得不被尊重；再表达自己的感受和需要；最后提出可执行的修复请求或承诺。解释动机可以放在后面，因为如果先解释，容易被听成辩解。修复也包括聆听对方版本，不急着纠正其中每个细节。道歉不是自我贬低，而是对关系的负责；原谅也不是立刻恢复原状，而是双方重新建立安全感和边界。若伤害反复发生，修复需要具体行为变化，而不只是情绪表达。App 可用于道歉、冷战后复联、伴侣争吵、朋友误会、亲子冲突和职场关系恢复。","tags":["关系修复","道歉","影响","安全感","冷战","亲密关系","沟通模板"],"status":"enabled","source":"seed:xinzhili-essence-20260704","sort":500}]$json$::jsonb)
  AS x(
    id bigint,
