SELECT id, title, content, tags, status, source, sort, now()
FROM seed
ON CONFLICT (id) DO UPDATE
SET title = EXCLUDED.title,
    content = EXCLUDED.content,
    tags = EXCLUDED.tags,
    status = EXCLUDED.status,
    source = EXCLUDED.source,
    sort = EXCLUDED.sort,
    update_time = now();

-- 如果当前库已启用 pgvector，则清空本批种子旧 embedding，避免内容更新后向量仍旧。
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='rag_documents' AND column_name='embedding_model') THEN
    UPDATE rag_documents
       SET embedding_model='', embedded_at=NULL
     WHERE source='seed:xinzhili-essence-20260704';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='rag_documents' AND column_name='embedding') THEN
    UPDATE rag_documents
       SET embedding=NULL
     WHERE source='seed:xinzhili-essence-20260704';
  END IF;
END $$;

SELECT setval(
  pg_get_serial_sequence('rag_documents', 'id'),
  COALESCE((SELECT max(id) FROM rag_documents), 1),
  true
);

COMMIT;
